CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Public @name people search for and pay. Unique and compared case-insensitively, because paying the wrong person is unrecoverable.
	"handle" VARCHAR(30) NOT NULL UNIQUE,
	-- Name shown in the feed. Free text, so it can never be used to identify a payee on its own.
	"display_name" VARCHAR(120) NOT NULL,
	-- Login identity and receipt address.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- E.164. Also the main way friends find each other from a contact list.
	"phone" VARCHAR(32) UNIQUE,
	-- Profile image. Null falls back to initials.
	"avatar_url" VARCHAR(512),
	-- public | friends | private. The default copied onto each new transfer, never read at display time, so changing it does not rewrite the past.
	"default_audience" VARCHAR(12) NOT NULL DEFAULT 'friends',
	-- unverified | pending | verified. Unverified users have hard caps on how much they can send and cannot cash out.
	"identity_status" VARCHAR(16) NOT NULL DEFAULT 'unverified',
	-- Blocks sending and cashing out during a fraud review while leaving the account readable.
	"is_frozen" BOOLEAN NOT NULL DEFAULT false,
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Soft close. Transfers and feed history must keep resolving to a name after someone leaves.
	"deactivated_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A person on the network. Rows are soft-closed rather than deleted because every transfer, comment and split in the system points at one and a payment with no counterparty is unreadable.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."handle" IS 'Public @name people search for and pay. Unique and compared case-insensitively, because paying the wrong person is unrecoverable.';
COMMENT ON COLUMN "users"."display_name" IS 'Name shown in the feed. Free text, so it can never be used to identify a payee on its own.';
COMMENT ON COLUMN "users"."email" IS 'Login identity and receipt address.';
COMMENT ON COLUMN "users"."phone" IS 'E.164. Also the main way friends find each other from a contact list.';
COMMENT ON COLUMN "users"."avatar_url" IS 'Profile image. Null falls back to initials.';
COMMENT ON COLUMN "users"."default_audience" IS 'public | friends | private. The default copied onto each new transfer, never read at display time, so changing it does not rewrite the past.';
COMMENT ON COLUMN "users"."identity_status" IS 'unverified | pending | verified. Unverified users have hard caps on how much they can send and cannot cash out.';
COMMENT ON COLUMN "users"."is_frozen" IS 'Blocks sending and cashing out during a fraud review while leaving the account readable.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';
COMMENT ON COLUMN "users"."deactivated_at" IS 'Soft close. Transfers and feed history must keep resolving to a name after someone leaves.';

CREATE TABLE IF NOT EXISTS "wallets" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner. One wallet per user per currency.
	"user_id" BIGINT NOT NULL,
	-- ISO 4217. A wallet holds exactly one currency; a second currency is a second wallet.
	"currency_code" CHAR(3) NOT NULL,
	-- Stored balance in minor units, maintained by the same transaction that appends a wallet entry. The entries, not this column, are the source of truth.
	"balance_minor" BIGINT NOT NULL DEFAULT 0,
	-- Money committed to in-flight cash-outs. Subtracting it is what stops someone spending the same balance twice while a bank transfer is still moving.
	"pending_out_minor" BIGINT NOT NULL DEFAULT 0,
	-- active | restricted | closed. Restricted still receives money but cannot send.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Wallet creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "wallets" IS 'The stored balance a user can spend without touching a bank. Keeping it separate from users means a balance of zero is a real state rather than a null, and a closed account still has a wallet that must reconcile to zero.';
COMMENT ON COLUMN "wallets"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "wallets"."user_id" IS 'Owner. One wallet per user per currency.';
COMMENT ON COLUMN "wallets"."currency_code" IS 'ISO 4217. A wallet holds exactly one currency; a second currency is a second wallet.';
COMMENT ON COLUMN "wallets"."balance_minor" IS 'Stored balance in minor units, maintained by the same transaction that appends a wallet entry. The entries, not this column, are the source of truth.';
COMMENT ON COLUMN "wallets"."pending_out_minor" IS 'Money committed to in-flight cash-outs. Subtracting it is what stops someone spending the same balance twice while a bank transfer is still moving.';
COMMENT ON COLUMN "wallets"."status" IS 'active | restricted | closed. Restricted still receives money but cannot send.';
COMMENT ON COLUMN "wallets"."created_at" IS 'Wallet creation time.';

CREATE UNIQUE INDEX "uq_wallets_user_currency"
ON "wallets" ("user_id", "currency_code");

CREATE TABLE IF NOT EXISTS "funding_sources" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner of the instrument.
	"user_id" BIGINT NOT NULL,
	-- bank_account | debit_card | credit_card. The type decides the fee, the speed and whether it can receive a cash-out.
	"source_type" VARCHAR(16) NOT NULL,
	-- Vault token standing in for the real credentials. Account and card numbers never enter this database.
	"processor_token" VARCHAR(128) NOT NULL UNIQUE,
	-- Bank or card issuer name, shown in the picker.
	"institution_name" VARCHAR(120),
	-- Last four digits, the only part safe to display.
	"last_four" CHAR(4) NOT NULL,
	-- visa | mastercard for cards, null for bank accounts.
	"brand" VARCHAR(20),
	-- pending | microdeposits_sent | verified | failed. A bank account cannot fund a payment until it is verified.
	"verification_status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- Preselected source when the wallet balance is short. At most one true per user, enforced in application code.
	"is_default" BOOLEAN NOT NULL DEFAULT false,
	-- Credit cards can pay in but never receive a cash-out, which is why this is a separate flag from verification.
	"can_receive_payout" BOOLEAN NOT NULL DEFAULT false,
	-- When the instrument was attached.
	"linked_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Soft removal. Old transfers still have to name the source that funded them.
	"removed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "funding_sources" IS 'A bank account or card attached to a user. Payments fall back to these when the wallet balance is short, which is why the fee model lives here and not on the transfer.';
COMMENT ON COLUMN "funding_sources"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "funding_sources"."user_id" IS 'Owner of the instrument.';
COMMENT ON COLUMN "funding_sources"."source_type" IS 'bank_account | debit_card | credit_card. The type decides the fee, the speed and whether it can receive a cash-out.';
COMMENT ON COLUMN "funding_sources"."processor_token" IS 'Vault token standing in for the real credentials. Account and card numbers never enter this database.';
COMMENT ON COLUMN "funding_sources"."institution_name" IS 'Bank or card issuer name, shown in the picker.';
COMMENT ON COLUMN "funding_sources"."last_four" IS 'Last four digits, the only part safe to display.';
COMMENT ON COLUMN "funding_sources"."brand" IS 'visa | mastercard for cards, null for bank accounts.';
COMMENT ON COLUMN "funding_sources"."verification_status" IS 'pending | microdeposits_sent | verified | failed. A bank account cannot fund a payment until it is verified.';
COMMENT ON COLUMN "funding_sources"."is_default" IS 'Preselected source when the wallet balance is short. At most one true per user, enforced in application code.';
COMMENT ON COLUMN "funding_sources"."can_receive_payout" IS 'Credit cards can pay in but never receive a cash-out, which is why this is a separate flag from verification.';
COMMENT ON COLUMN "funding_sources"."linked_at" IS 'When the instrument was attached.';
COMMENT ON COLUMN "funding_sources"."removed_at" IS 'Soft removal. Old transfers still have to name the source that funded them.';

CREATE INDEX "idx_funding_user_status"
ON "funding_sources" ("user_id", "verification_status");

CREATE TABLE IF NOT EXISTS "transfers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- User paying.
	"sender_id" BIGINT NOT NULL,
	-- User being paid. Both sides are required: this schema has no concept of paying an address.
	"recipient_id" BIGINT NOT NULL,
	-- Wallet debited. Fixes the currency of the transfer.
	"sender_wallet_id" BIGINT NOT NULL,
	-- Wallet credited. Must share the currency of the sender wallet.
	"recipient_wallet_id" BIGINT NOT NULL,
	-- Instrument covering whatever the wallet balance did not. Null for a transfer paid entirely from balance, which is also the only free path.
	"funding_source_id" BIGINT,
	-- Set when this transfer settles a request someone sent. This is what closes the loop between asking and paying.
	"payment_request_id" BIGINT,
	-- Client-generated key. A double-tapped send button is the single most common bug in a payments app, and this column is the fix.
	"idempotency_key" VARCHAR(64) NOT NULL UNIQUE,
	-- Amount moved, in minor units. Integer only.
	"amount_minor" BIGINT NOT NULL,
	-- ISO 4217, matching both wallets.
	"currency_code" CHAR(3) NOT NULL,
	-- Fee charged to the sender for using a card. Stored on the transfer because it is part of what the sender agreed to, not a property of the source.
	"fee_minor" BIGINT NOT NULL DEFAULT 0,
	-- The message every payment carries. Required, because a feed entry with no reason is the one thing the product cannot render.
	"note_text" VARCHAR(280) NOT NULL,
	-- public | friends | private. Copied from the sender default at creation and frozen: making a profile private later must not retroactively hide a payment a friend already saw.
	"audience" VARCHAR(12) NOT NULL DEFAULT 'friends',
	-- pending | completed | failed | reversed. Pending is short but real while a card authorisation clears.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- insufficient_funds | source_declined | recipient_frozen | limit_exceeded.
	"failure_reason" VARCHAR(64),
	-- When the send was submitted.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When both wallet entries were written.
	"completed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "transfers" IS 'One payment from one person to another, and simultaneously one story in the feed. Merging the two is the product insight of this schema: the social object and the money object are the same row, so they can never disagree.';
COMMENT ON COLUMN "transfers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "transfers"."sender_id" IS 'User paying.';
COMMENT ON COLUMN "transfers"."recipient_id" IS 'User being paid. Both sides are required: this schema has no concept of paying an address.';
COMMENT ON COLUMN "transfers"."sender_wallet_id" IS 'Wallet debited. Fixes the currency of the transfer.';
COMMENT ON COLUMN "transfers"."recipient_wallet_id" IS 'Wallet credited. Must share the currency of the sender wallet.';
COMMENT ON COLUMN "transfers"."funding_source_id" IS 'Instrument covering whatever the wallet balance did not. Null for a transfer paid entirely from balance, which is also the only free path.';
COMMENT ON COLUMN "transfers"."payment_request_id" IS 'Set when this transfer settles a request someone sent. This is what closes the loop between asking and paying.';
COMMENT ON COLUMN "transfers"."idempotency_key" IS 'Client-generated key. A double-tapped send button is the single most common bug in a payments app, and this column is the fix.';
COMMENT ON COLUMN "transfers"."amount_minor" IS 'Amount moved, in minor units. Integer only.';
COMMENT ON COLUMN "transfers"."currency_code" IS 'ISO 4217, matching both wallets.';
COMMENT ON COLUMN "transfers"."fee_minor" IS 'Fee charged to the sender for using a card. Stored on the transfer because it is part of what the sender agreed to, not a property of the source.';
COMMENT ON COLUMN "transfers"."note_text" IS 'The message every payment carries. Required, because a feed entry with no reason is the one thing the product cannot render.';
COMMENT ON COLUMN "transfers"."audience" IS 'public | friends | private. Copied from the sender default at creation and frozen: making a profile private later must not retroactively hide a payment a friend already saw.';
COMMENT ON COLUMN "transfers"."status" IS 'pending | completed | failed | reversed. Pending is short but real while a card authorisation clears.';
COMMENT ON COLUMN "transfers"."failure_reason" IS 'insufficient_funds | source_declined | recipient_frozen | limit_exceeded.';
COMMENT ON COLUMN "transfers"."created_at" IS 'When the send was submitted.';
COMMENT ON COLUMN "transfers"."completed_at" IS 'When both wallet entries were written.';

CREATE INDEX "idx_transfers_sender_created"
ON "transfers" ("sender_id", "created_at");
CREATE INDEX "idx_transfers_recipient_created"
ON "transfers" ("recipient_id", "created_at");
CREATE INDEX "idx_transfers_feed"
ON "transfers" ("audience", "created_at");

CREATE TABLE IF NOT EXISTS "payment_requests" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- User asking to be paid.
	"requester_id" BIGINT NOT NULL,
	-- User being asked.
	"payer_id" BIGINT NOT NULL,
	-- Parent split, when this ask is one share of a bill. Null for a standalone request.
	"split_request_id" BIGINT,
	-- Amount asked for, in minor units.
	"amount_minor" BIGINT NOT NULL,
	-- ISO 4217.
	"currency_code" CHAR(3) NOT NULL,
	-- What the money is for. Carried onto the transfer when the request is paid, so the feed reads the same either way.
	"note_text" VARCHAR(280) NOT NULL,
	-- pending | paid | declined | canceled | expired. A request is a message, not a debt, so declining it is a first-class outcome.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Last nudge. Rate-limited so the product does not turn friends into a collections department.
	"reminded_at" TIMESTAMPTZ,
	-- When the ask stops appearing in the payer list. Null means it stays until acted on.
	"expires_at" TIMESTAMPTZ,
	-- When the request was sent.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When it was paid, declined or cancelled.
	"resolved_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "payment_requests" IS 'An ask, pointing the opposite way to a transfer. It is deliberately not a pending transfer: no money is reserved, the payer can decline, and nothing about it touches a wallet until a real transfer is created.';
COMMENT ON COLUMN "payment_requests"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "payment_requests"."requester_id" IS 'User asking to be paid.';
COMMENT ON COLUMN "payment_requests"."payer_id" IS 'User being asked.';
COMMENT ON COLUMN "payment_requests"."split_request_id" IS 'Parent split, when this ask is one share of a bill. Null for a standalone request.';
COMMENT ON COLUMN "payment_requests"."amount_minor" IS 'Amount asked for, in minor units.';
COMMENT ON COLUMN "payment_requests"."currency_code" IS 'ISO 4217.';
COMMENT ON COLUMN "payment_requests"."note_text" IS 'What the money is for. Carried onto the transfer when the request is paid, so the feed reads the same either way.';
COMMENT ON COLUMN "payment_requests"."status" IS 'pending | paid | declined | canceled | expired. A request is a message, not a debt, so declining it is a first-class outcome.';
COMMENT ON COLUMN "payment_requests"."reminded_at" IS 'Last nudge. Rate-limited so the product does not turn friends into a collections department.';
COMMENT ON COLUMN "payment_requests"."expires_at" IS 'When the ask stops appearing in the payer list. Null means it stays until acted on.';
COMMENT ON COLUMN "payment_requests"."created_at" IS 'When the request was sent.';
COMMENT ON COLUMN "payment_requests"."resolved_at" IS 'When it was paid, declined or cancelled.';

CREATE INDEX "idx_requests_payer_status"
ON "payment_requests" ("payer_id", "status");
CREATE INDEX "idx_requests_requester_created"
ON "payment_requests" ("requester_id", "created_at");

CREATE TABLE IF NOT EXISTS "split_requests" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- User who paid the bill and is splitting it.
	"organizer_id" BIGINT NOT NULL,
	-- Full bill in minor units, including the organizer own share. Stored so rounding remainders can be reconciled against the shares.
	"total_minor" BIGINT NOT NULL,
	-- ISO 4217.
	"currency_code" CHAR(3) NOT NULL,
	-- What the bill was for, inherited by every share.
	"note_text" VARCHAR(280) NOT NULL,
	-- equal | exact | percentage. Kept so the split can be re-explained and edited later without guessing from the amounts.
	"split_method" VARCHAR(16) NOT NULL DEFAULT 'equal',
	-- open | settled | canceled. Settled when every participant share is paid or written off.
	"status" VARCHAR(16) NOT NULL DEFAULT 'open',
	-- When the split was created.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the last share closed.
	"settled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "split_requests" IS 'The header for a bill split. It exists so the organizer sees one row saying who still owes rather than a scatter of unrelated requests, and so a rounding remainder has an owner.';
COMMENT ON COLUMN "split_requests"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "split_requests"."organizer_id" IS 'User who paid the bill and is splitting it.';
COMMENT ON COLUMN "split_requests"."total_minor" IS 'Full bill in minor units, including the organizer own share. Stored so rounding remainders can be reconciled against the shares.';
COMMENT ON COLUMN "split_requests"."currency_code" IS 'ISO 4217.';
COMMENT ON COLUMN "split_requests"."note_text" IS 'What the bill was for, inherited by every share.';
COMMENT ON COLUMN "split_requests"."split_method" IS 'equal | exact | percentage. Kept so the split can be re-explained and edited later without guessing from the amounts.';
COMMENT ON COLUMN "split_requests"."status" IS 'open | settled | canceled. Settled when every participant share is paid or written off.';
COMMENT ON COLUMN "split_requests"."created_at" IS 'When the split was created.';
COMMENT ON COLUMN "split_requests"."settled_at" IS 'When the last share closed.';

CREATE TABLE IF NOT EXISTS "split_participants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent split.
	"split_request_id" BIGINT NOT NULL,
	-- Person on the hook for this share.
	"user_id" BIGINT NOT NULL,
	-- The ask generated for this share. Null for the organizer own share, which is never requested from themselves.
	"payment_request_id" BIGINT,
	-- This share in minor units. Shares sum exactly to the split total; the remainder from an uneven division is added to the organizer share rather than dropped.
	"share_minor" BIGINT NOT NULL,
	-- For a percentage or exact split, the input that produced share_minor. Kept so editing the split recomputes from intent, not from rounded money.
	"share_basis" VARCHAR(16),
	-- owed | paid | declined | forgiven. Forgiven is what lets an organizer close a split without chasing someone.
	"status" VARCHAR(16) NOT NULL DEFAULT 'owed',
	-- When this share was paid or written off.
	"settled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "split_participants" IS 'One row per person in a split. Making it a table rather than a JSON blob on the split is what lets a participant be chased, reminded and settled individually.';
COMMENT ON COLUMN "split_participants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "split_participants"."split_request_id" IS 'Parent split.';
COMMENT ON COLUMN "split_participants"."user_id" IS 'Person on the hook for this share.';
COMMENT ON COLUMN "split_participants"."payment_request_id" IS 'The ask generated for this share. Null for the organizer own share, which is never requested from themselves.';
COMMENT ON COLUMN "split_participants"."share_minor" IS 'This share in minor units. Shares sum exactly to the split total; the remainder from an uneven division is added to the organizer share rather than dropped.';
COMMENT ON COLUMN "split_participants"."share_basis" IS 'For a percentage or exact split, the input that produced share_minor. Kept so editing the split recomputes from intent, not from rounded money.';
COMMENT ON COLUMN "split_participants"."status" IS 'owed | paid | declined | forgiven. Forgiven is what lets an organizer close a split without chasing someone.';
COMMENT ON COLUMN "split_participants"."settled_at" IS 'When this share was paid or written off.';

CREATE UNIQUE INDEX "uq_split_participants_split_user"
ON "split_participants" ("split_request_id", "user_id");

CREATE TABLE IF NOT EXISTS "funding_transfers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner of both ends of the movement.
	"user_id" BIGINT NOT NULL,
	-- Wallet gaining or losing the money.
	"wallet_id" BIGINT NOT NULL,
	-- Bank account or card on the other side.
	"funding_source_id" BIGINT NOT NULL,
	-- top_up | cash_out. Stored explicitly so the sign of a movement is never inferred from context.
	"direction" VARCHAR(8) NOT NULL,
	-- Amount moved, in minor units.
	"amount_minor" BIGINT NOT NULL,
	-- ISO 4217, matching the wallet.
	"currency_code" CHAR(3) NOT NULL,
	-- Instant cash-out fee. Standard cash-outs are free and slow, which is the entire pricing model.
	"fee_minor" BIGINT NOT NULL DEFAULT 0,
	-- standard | instant.
	"speed" VARCHAR(12) NOT NULL DEFAULT 'standard',
	-- pending | completed | failed | returned. Returned happens days later when a bank rejects the credit, which is why the wallet must hold pending_out separately.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Reference at the bank or card processor. Unique so a replayed settlement file cannot move money twice.
	"external_reference" VARCHAR(64) UNIQUE,
	-- When the movement was requested.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the bank confirmed it.
	"completed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "funding_transfers" IS 'Money entering or leaving the network. Peer transfers only shuffle balances inside the system; this is the only table where money actually crosses the boundary, which makes it the only place a bank can reverse something.';
COMMENT ON COLUMN "funding_transfers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "funding_transfers"."user_id" IS 'Owner of both ends of the movement.';
COMMENT ON COLUMN "funding_transfers"."wallet_id" IS 'Wallet gaining or losing the money.';
COMMENT ON COLUMN "funding_transfers"."funding_source_id" IS 'Bank account or card on the other side.';
COMMENT ON COLUMN "funding_transfers"."direction" IS 'top_up | cash_out. Stored explicitly so the sign of a movement is never inferred from context.';
COMMENT ON COLUMN "funding_transfers"."amount_minor" IS 'Amount moved, in minor units.';
COMMENT ON COLUMN "funding_transfers"."currency_code" IS 'ISO 4217, matching the wallet.';
COMMENT ON COLUMN "funding_transfers"."fee_minor" IS 'Instant cash-out fee. Standard cash-outs are free and slow, which is the entire pricing model.';
COMMENT ON COLUMN "funding_transfers"."speed" IS 'standard | instant.';
COMMENT ON COLUMN "funding_transfers"."status" IS 'pending | completed | failed | returned. Returned happens days later when a bank rejects the credit, which is why the wallet must hold pending_out separately.';
COMMENT ON COLUMN "funding_transfers"."external_reference" IS 'Reference at the bank or card processor. Unique so a replayed settlement file cannot move money twice.';
COMMENT ON COLUMN "funding_transfers"."created_at" IS 'When the movement was requested.';
COMMENT ON COLUMN "funding_transfers"."completed_at" IS 'When the bank confirmed it.';

CREATE INDEX "idx_funding_transfers_user_created"
ON "funding_transfers" ("user_id", "created_at");

CREATE TABLE IF NOT EXISTS "wallet_entries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Wallet whose balance moves.
	"wallet_id" BIGINT NOT NULL,
	-- transfer_in | transfer_out | top_up | cash_out | fee | reversal | adjustment.
	"entry_type" VARCHAR(20) NOT NULL,
	-- Source peer transfer, when the movement came from one.
	"transfer_id" BIGINT,
	-- Source top-up or cash-out, when the movement came from one.
	"funding_transfer_id" BIGINT,
	-- Signed amount in minor units. Negative leaves the wallet. A peer payment writes two rows, one negative and one positive, that sum to zero.
	"amount_minor" BIGINT NOT NULL,
	-- Wallet balance after this entry. Written by the same transaction so a statement never needs a window function over all history.
	"balance_after_minor" BIGINT NOT NULL,
	-- Write time. Entries are append-only: a correction is a new entry, never an update.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "wallet_entries" IS 'The append-only journal behind every balance. A peer transfer inserts the debit and the credit in one database transaction, so the network as a whole always nets to what has actually been funded.';
COMMENT ON COLUMN "wallet_entries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "wallet_entries"."wallet_id" IS 'Wallet whose balance moves.';
COMMENT ON COLUMN "wallet_entries"."entry_type" IS 'transfer_in | transfer_out | top_up | cash_out | fee | reversal | adjustment.';
COMMENT ON COLUMN "wallet_entries"."transfer_id" IS 'Source peer transfer, when the movement came from one.';
COMMENT ON COLUMN "wallet_entries"."funding_transfer_id" IS 'Source top-up or cash-out, when the movement came from one.';
COMMENT ON COLUMN "wallet_entries"."amount_minor" IS 'Signed amount in minor units. Negative leaves the wallet. A peer payment writes two rows, one negative and one positive, that sum to zero.';
COMMENT ON COLUMN "wallet_entries"."balance_after_minor" IS 'Wallet balance after this entry. Written by the same transaction so a statement never needs a window function over all history.';
COMMENT ON COLUMN "wallet_entries"."created_at" IS 'Write time. Entries are append-only: a correction is a new entry, never an update.';

CREATE INDEX "idx_wallet_entries_wallet_created"
ON "wallet_entries" ("wallet_id", "created_at");

CREATE TABLE IF NOT EXISTS "friendships" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- User who sent the request. Ordering matters here: the pair is stored once, not twice.
	"user_id" BIGINT NOT NULL,
	-- User who received it.
	"friend_id" BIGINT NOT NULL,
	-- pending | accepted | blocked. Blocked also removes both users from each other feeds.
	"status" VARCHAR(12) NOT NULL DEFAULT 'pending',
	-- contacts | search | transfer | facebook. Kept because friend suggestions are the main growth loop and need to know what worked.
	"source" VARCHAR(16),
	-- When the request was sent.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When it was accepted. Null while pending.
	"accepted_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "friendships" IS 'The social graph that the friends audience resolves against. One row per pair rather than two mirrored rows, which means every feed query has to check both columns and is worth it to keep the pair from ever disagreeing with itself.';
COMMENT ON COLUMN "friendships"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "friendships"."user_id" IS 'User who sent the request. Ordering matters here: the pair is stored once, not twice.';
COMMENT ON COLUMN "friendships"."friend_id" IS 'User who received it.';
COMMENT ON COLUMN "friendships"."status" IS 'pending | accepted | blocked. Blocked also removes both users from each other feeds.';
COMMENT ON COLUMN "friendships"."source" IS 'contacts | search | transfer | facebook. Kept because friend suggestions are the main growth loop and need to know what worked.';
COMMENT ON COLUMN "friendships"."created_at" IS 'When the request was sent.';
COMMENT ON COLUMN "friendships"."accepted_at" IS 'When it was accepted. Null while pending.';

CREATE UNIQUE INDEX "uq_friendships_pair"
ON "friendships" ("user_id", "friend_id");
CREATE INDEX "idx_friendships_friend_status"
ON "friendships" ("friend_id", "status");

CREATE TABLE IF NOT EXISTS "transfer_comments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Transfer being commented on.
	"transfer_id" BIGINT NOT NULL,
	-- Commenter. Must be able to see the transfer under its audience, checked at write time as well as read time.
	"author_id" BIGINT NOT NULL,
	-- Comment text, usually emoji.
	"body" VARCHAR(500) NOT NULL,
	-- Post time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Soft delete, so a removed comment does not renumber a thread someone is reading.
	"deleted_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "transfer_comments" IS 'Comments hang off the transfer, not off a separate post object. There is no post: the payment is the post, which is why a private transfer simply has no readers rather than a hidden thread.';
COMMENT ON COLUMN "transfer_comments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "transfer_comments"."transfer_id" IS 'Transfer being commented on.';
COMMENT ON COLUMN "transfer_comments"."author_id" IS 'Commenter. Must be able to see the transfer under its audience, checked at write time as well as read time.';
COMMENT ON COLUMN "transfer_comments"."body" IS 'Comment text, usually emoji.';
COMMENT ON COLUMN "transfer_comments"."created_at" IS 'Post time.';
COMMENT ON COLUMN "transfer_comments"."deleted_at" IS 'Soft delete, so a removed comment does not renumber a thread someone is reading.';

CREATE INDEX "idx_comments_transfer_created"
ON "transfer_comments" ("transfer_id", "created_at");

CREATE TABLE IF NOT EXISTS "transfer_likes" (
	-- Transfer liked. Half of the composite primary key.
	"transfer_id" BIGINT,
	-- User who liked it. The composite key makes a double tap idempotent at the database level rather than in application code.
	"user_id" BIGINT,
	-- When the like was added. Unliking deletes the row outright, because nobody audits a like.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("transfer_id", "user_id")
);

COMMENT ON TABLE "transfer_likes" IS 'A join table with no surrogate id, deliberately. The pair is the identity, so the uniqueness that stops duplicate likes is the primary key itself instead of an extra constraint.';
COMMENT ON COLUMN "transfer_likes"."transfer_id" IS 'Transfer liked. Half of the composite primary key.';
COMMENT ON COLUMN "transfer_likes"."user_id" IS 'User who liked it. The composite key makes a double tap idempotent at the database level rather than in application code.';
COMMENT ON COLUMN "transfer_likes"."created_at" IS 'When the like was added. Unliking deletes the row outright, because nobody audits a like.';

CREATE INDEX "idx_likes_user_created"
ON "transfer_likes" ("user_id", "created_at");

